} from "./live-voice-workspace";
import { parseLiveAction, type LiveAction } from "./live-voice-contract";

export type LiveVoiceStatus =
  | "idle"
  | "connecting"
  | "listening"
  | "speaking"
  | "closing"
  | "error";
export interface LiveVoiceTurn {
  role: "user" | "assistant";
  text: string;
}
export interface LiveVoiceState {
  status: LiveVoiceStatus;
  author: string;
  muted: boolean;
  level: number;
  startedAt: number;
  userTranscript: string;
  assistantTranscript: string;
  /** The conversation as alternating turns, newest last, for captions. */
  turns: LiveVoiceTurn[];
  notice: string;
  error: string;
  pending: LiveAction | null;
  working: boolean;
  finalized: boolean;
  sources: Array<{ title: string; url: string; snippet: string }>;
}
const state: LiveVoiceState = {
  status: "idle",
  author: "Le Lecteur",
  muted: false,
  level: 0,
  startedAt: 0,
  userTranscript: "",
  assistantTranscript: "",
  turns: [],
  notice: "",
  error: "",
  pending: null,
  working: false,
  finalized: false,
  sources: [],
};
const MAX_TURNS = 40;
export const LIVE_STATE_EVENT = "twyne:live-voice";
export function liveVoiceState(): LiveVoiceState {
  return {
    ...state,
    pending: state.pending && { ...state.pending },
    sources: [...state.sources],
    turns: state.turns.map((turn) => ({ ...turn })),
  };
}

/**
 * Spoken, an editor is recognised by habit rather than typography: their
 * moves and sample lines, never the guillemets or bold rulings of the page.
 */
function spokenHabits(persona: {
  signatureMoves?: string[];
  sampleLines?: string[];
}): string {
  const moves = persona.signatureMoves?.slice(0, 3) ?? [];
  const lines = (persona.sampleLines ?? [])
    .slice(0, 2)
    .map((line) => line.replace(/[*_«»]/g, "").replace(/\s*\n\s*/g, " "));
  return [
    moves.length ? `\nHabits you keep in conversation: ${moves.join(" ")}` : "",
    lines.length
      ? `\nHow you sound (never repeat verbatim): ${lines.map((l) => `"${l}"`).join(" ")}`
      : "",
  ].join("");
}

/**
 * Microphone and voice loudness, 0–1, sampled at call time. For animation
 * frames: reading these through `liveVoiceState` would re-render the desk
 * on every frame.
 */
export function liveVoiceLevels(): { input: number; output: number } {
  return {
    input: state.muted ? 0 : state.level,
    output: audio?.outputLevel() ?? 0,
  };
}
function emit() {
  window.dispatchEvent(new Event(LIVE_STATE_EVENT));
}
let socket: WebSocket | null = null;
let audio: Awaited<ReturnType<typeof liveVoiceAudio>> | null = null;
let generation = 0;
let startTimer: ReturnType<typeof setTimeout> | undefined;
let endTimer: ReturnType<typeof setTimeout> | undefined;
let pendingRevision = "";
let pendingUserSpeech = "";
let history: string[] = [];
let cleanupEvents = () => {};

function send(event: unknown) {
  if (
    !socket ||
    socket.readyState !== WebSocket.OPEN ||
    socket.bufferedAmount > 256_000
  )
    throw new Error("Live connection is unavailable or too slow.");
  socket.send(JSON.stringify(event));
}
function feedback(content: string, delegationId: string | null = null) {
  state.notice = content;
  emit();
  try {
    send({
      type: "session.commentary.append",
      event_id: crypto.randomUUID(),
      delegation_id: delegationId,
      content: content.slice(0, 480),
    });
  } catch {
    finish("Live disconnected while returning a task result.");
  }
}
function finish(error = "", finalized = false) {
  generation++;
  clearTimeout(startTimer);
  clearTimeout(endTimer);
  audio?.stop();
  audio = null;
  const previous = socket;
  socket = null;
  if (previous && previous.readyState < WebSocket.CLOSING) previous.close();
  cleanupEvents();
  cleanupEvents = () => {};
  state.status = error ? "error" : "idle";
  state.error = error;
  state.level = 0;
  state.working = false;
  state.finalized = finalized;
  state.pending = null;
  pendingRevision = "";
  pendingUserSpeech = "";
  emit();
}
export function endLiveVoice() {
  if (state.status === "closing") return;
  audio?.stop();
  audio = null;
  if (!socket || socket.readyState !== WebSocket.OPEN) {
    finish();
    return;
  }
  state.status = "closing";
  state.pending = null;
  state.level = 0;
  emit();
  clearTimeout(startTimer);
  try {
    send({ type: "session.close" });
  } catch {
    finish("Disconnected. Final credit usage could not be confirmed.");
    return;
  }
  endTimer = setTimeout(
    () =>
      finish(
        "Session ended without a final usage receipt. Check your wallet for the settled charge.",
      ),
    16_000,
  );
}
export function muteLiveVoice() {
  if (!["listening", "speaking"].includes(state.status)) return;
  state.muted = !state.muted;
  audio?.mute(state.muted);
  try {
    send({
      type: state.muted
        ? "session.input_audio.mute"
        : "session.input_audio.unmute",
      event_id: crypto.randomUUID(),
    });
  } catch (error) {
    finish(String(error));
  }
  emit();
}
export function applyPendingVoiceEdit() {
  if (!state.pending) return "There is no pending edit.";
  const result = applyVoiceEdit(state.pending, pendingRevision);
  state.pending = null;
  pendingRevision = "";
  history.push(result);
  emit();
  return result;
}
export function reviewVoiceEdit(apply: boolean) {
  try {
    const result = apply
      ? applyPendingVoiceEdit()
      : "Discarded the proposed edit.";
    if (!apply) {
      state.pending = null;
      pendingRevision = "";
    }
    feedback(result);
  } catch (error) {
    state.notice =
      error instanceof Error ? error.message : "The edit could not be applied.";
    emit();
  }
}

