    ) {
      return JSON.stringify({ type: event.type, event_id: eventId });
    }
    if (
      [
        "session.instructions.append",
        "session.thinking.append",
        "session.commentary.append",
      ].includes(String(event.type))
    ) {
      if (
        typeof event.content !== "string" ||
        !event.content.length ||
        (this.productPolicy ? Buffer.byteLength(event.content) > 1500 : event.content.length > 500) ||
        (event.delegation_id !== null &&
          (typeof event.delegation_id !== "string" || !this.clientDelegations.has(event.delegation_id)))
      )
        throw invalid();
      return JSON.stringify({
        type: event.type,
        event_id: eventId,
        content: event.content,
        delegation_id: event.delegation_id,
      });
    }
    // No response.create, arbitrary tools, model/voice changes, storage, or usage injection.
    throw invalid();
  }

  serverMessage(message: string): boolean {
    let event: { type?: string; usage?: { seconds?: unknown }; delegation?: { id?: unknown; target?: unknown } };
    try {
      event = JSON.parse(message);
    } catch {
      return false;
    }
    if (!event || typeof event !== "object") return false;
    if (event.type === "session.started" && !this.ready) {
      this.ready = true;
      this.startedAt = this.now();
    }
    if (event.type === "session.delegation.created" && this.ready &&
      event.delegation?.target === "client" && typeof event.delegation.id === "string" && event.delegation.id.length <= 128) {
      this.clientDelegations.add(event.delegation.id);
      if (this.clientDelegations.size > 128) this.clientDelegations.delete(this.clientDelegations.values().next().value!);
    }
    if (event.type !== "session.closed") return false;
    this.closing = true;
    const seconds = event.usage?.seconds;
    if (typeof seconds === "number" && Number.isFinite(seconds) && seconds >= 0)
      this.finalSeconds = seconds;
    return true;
  }
}

export async function liveContext(
  config: GatewayConfig,
  request: Request,
  principal: VerifiedPrincipal,
): Promise<RealtimeUpgradeContext> {
  const live = config.live;
  const upstreamPerMinute = live?.upstreamMicrousdPerMinute ??
    (live?.upstreamMicrousdPerSecond === undefined ? 0 : live.upstreamMicrousdPerSecond * 60);
  if (
    !live?.apiKey ||
    !Number.isSafeInteger(upstreamPerMinute) ||
    upstreamPerMinute <= 0
  ) {
    throw new GatewayError(
      503,
      "api_error",
      "GPT-Live is not configured.",
      "live_unavailable",
    );
  }
  if (new URL(request.url).search)
    throw new GatewayError(
      400,
      "invalid_request_error",
      "Live does not accept query parameters.",
      "invalid_live_query",
    );
  if (config.enabledAliases && !config.enabledAliases.includes("realtime")) {
    throw new GatewayError(
      403,
      "permission_error",
      "Realtime is disabled.",
      "model_not_enabled",
    );
  }
  if (
    !(await config.store.hasRealtimeConsent({ accountId: principal.accountId }))
  ) {
    throw new GatewayError(
      403,
      "permission_error",
      "Live requires explicit content-logging consent.",
      "realtime_consent_required",
    );
  }
  // Keep the published minute rate exact; never round it to an integer second rate.
  const ratePerMinute = addProviderMarkup(upstreamPerMinute);
  const chargeForSeconds = (seconds: number) => Math.ceil(seconds * ratePerMinute / 60);
  const budget = Number(request.headers.get("x-notorganic-max-cost-microusd"));
  // Reserve 15 seconds for graceful close plus one second of rounding headroom.
  if (!Number.isSafeInteger(budget) || budget < chargeForSeconds(31)) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "Live budget must cover at least 31 seconds at the configured rate.",
      "live_budget_too_small",
    );
  }
  let maxSeconds: number | undefined;
  if (principal.product === "interleave") {
    maxSeconds = Number(request.headers.get("x-notorganic-live-max-seconds"));
    if (!Number.isSafeInteger(maxSeconds) || maxSeconds < 31 || maxSeconds > 1500 || budget < chargeForSeconds(maxSeconds)) {
      throw new GatewayError(400, "invalid_request_error", "Interleave Live requires 31–1500 maximum seconds and a budget covering that duration.", "invalid_live_duration");
    }
  }
  const proxy = new PortkeyProxy(config);
  const reservedBudget = maxSeconds === undefined ? budget : chargeForSeconds(maxSeconds);
  const reservationHeaders = new Headers(request.headers);
  reservationHeaders.set("x-notorganic-max-cost-microusd", String(reservedBudget));
  const reservation = await proxy.reserveRealtime(maxSeconds === undefined ? request : new Request(request, { headers: reservationHeaders }), principal, "live");
  const policy = new LiveSessionPolicy(
    (maxSeconds === undefined ? Math.min(25 * 60, Math.floor(budget * 60 / ratePerMinute) - 16) : maxSeconds - 16) * 1000,
    config.now,
    principal.product === "interleave" ? (live.products?.interleave ?? {}) : undefined,
  );
  let finalized = false;
  return {
    principal,
    revalidate: () => new TokenService(config).revalidate(principal),
    sessionPolicy: policy,
    upstreamUrl: "wss://api.openai.com/v1/live/sessions",
    upstreamHeaders: new Headers({ Authorization: `Bearer ${live.apiKey}` }),
    onAccepted: () => proxy.acceptRealtime(reservation.requestId),
    onClosed: async () => {
      if (finalized) return;
      finalized = true;
      if (!policy.dispatched) {
        await config.store.release({
          requestId: reservation.requestId,
          reason: "live_not_started",
        });
      } else if (policy.finalSeconds === undefined) {
        await config.store.reconcile({
          requestId: reservation.requestId,
          conservativeCostMicrousd: reservedBudget,
          reason: "live_final_usage_unconfirmed",
        });
      } else {
        // This route uses WebSockets. The documented 15-second initialization
        // charge belongs to WebRTC POST creation, not a WebSocket billing floor.
        const charge = chargeForSeconds(policy.finalSeconds);
        await config.store.settle({
          requestId: reservation.requestId,
          actualCostMicrousd: Math.min(charge, reservedBudget),
          providerAbsorbedMicrousd: Math.max(0, charge - reservedBudget),
          usage: {
            live_seconds: policy.finalSeconds,
            live_billable_seconds: policy.finalSeconds,
          },
        });
      }
    },
  };
}

