import type { RealtimeUpgrade, RealtimeUpgradeContext } from "./realtime";
import { startAuthorityHeartbeat, type AuthorityTimers, authorityTimers } from "./authority-heartbeat";

interface RelaySocketData {
  context: RealtimeUpgradeContext;
  upstream?: WebSocket;
  accepted: boolean;
  finalized: boolean;
  queue: Array<string | ArrayBuffer | Uint8Array>;
  queuedBytes: number;
  lifetimeTimer?: ReturnType<typeof setTimeout>;
  closeTimer?: ReturnType<typeof setTimeout>;
  closing?: boolean;
  stopAuthority?: () => void;
}

export class BunRealtimeRelay implements RealtimeUpgrade {
  private server?: Bun.Server<RelaySocketData>;
  constructor(private readonly timers: AuthorityTimers = authorityTimers) {}

  attach(server: Bun.Server<RelaySocketData>): void {
    this.server = server;
  }

  upgrade(request: Request, context: RealtimeUpgradeContext): Response {
    if (!this.server) throw new Error("Realtime relay is not attached");
    const upgraded = this.server.upgrade(request, {
      data: {
        context,
        accepted: false,
        finalized: false,
        queue: [],
        queuedBytes: 0,
      },
    });
    if (!upgraded) {
      void context
        .onClosed(false)
        .catch(() => console.error("Realtime accounting finalization failed"));
      return new Response("WebSocket upgrade failed", { status: 400 });
    }
    // Bun ignores the HTTP response after a successful server.upgrade call.
    return new Response(null, { status: 204 });
  }

  readonly websocket: Bun.WebSocketHandler<RelaySocketData> = {
    open: (client) => {
      const data = client.data;
      data.lifetimeTimer = setTimeout(
        () => this.beginClose(client),
        data.context.sessionPolicy?.maxDurationMs ?? 25 * 60_000,
      );
      const upstream = new WebSocket(data.context.upstreamUrl, {
        headers: Object.fromEntries(data.context.upstreamHeaders),
      } as never);
      data.upstream = upstream;
      data.stopAuthority = startAuthorityHeartbeat(() => data.context.revalidate(), () => {
        // Stop client access immediately. Live upstream may drain final usage
        // after session.close; this is settlement, not continuing user access.
        this.beginClose(client);
        client.close(1008, "session access revoked");
      }, this.timers);
      upstream.binaryType = "arraybuffer";
      upstream.addEventListener("open", () => {
        if (data.closing || data.finalized) {
          upstream.close();
          return;
        }
        void data.context.onAccepted().then(
          () => {
            if (data.finalized || data.closing) {
              upstream.close();
              return;
            }
            data.accepted = true;
            for (const queued of data.queue.splice(0))
              this.forward(client, queued);
            data.queuedBytes = 0;
          },
          () => {
            upstream.close(1011, "accounting initialization failed");
            client.close(1011, "accounting initialization failed");
          },
        );
      });
      upstream.addEventListener("message", (event) => {
        const terminal =
          typeof event.data === "string" &&
          data.context.sessionPolicy?.serverMessage(event.data);
        if (client.readyState === WebSocket.OPEN) {
          if (!data.closing && client.send(event.data) === -1) this.beginClose(client);
        }
        if (terminal) {
          upstream.close(1000, "session finalized");
          void this.finalize(data);
        }
      });
      upstream.addEventListener("close", (event) => {
        if (client.readyState === WebSocket.OPEN) {
          client.close(event.code || 1000, event.reason);
        }
        void this.finalize(data);
      });
      upstream.addEventListener("error", () => {
        if (client.readyState === WebSocket.OPEN) {
          client.close(1011, "upstream realtime connection failed");
        }
        void this.finalize(data);
      });
    },
    message: (_client, message) => {
      const data = _client.data;
      if (data.closing || data.finalized) return;
      if (data.upstream?.readyState === WebSocket.OPEN && data.accepted) {
        this.forward(_client, message);
      } else {
        const bytes =
          typeof message === "string"
            ? Buffer.byteLength(message)
            : message.byteLength;
        if (data.queue.length >= 64 || data.queuedBytes + bytes > 1_048_576) {
          _client.close(1009, "realtime preconnect queue limit exceeded");
          void this.finalize(data);
          return;
        }
        data.queue.push(message);
        data.queuedBytes += bytes;
      }
    },
    close: (client) => {
      const data = client.data;
      if (
        data.context.sessionPolicy &&
        data.upstream?.readyState === WebSocket.OPEN &&
        !data.finalized
      ) {
        this.beginClose(client);
        return;
      }
      if (
        data.upstream &&
        (data.upstream.readyState === WebSocket.OPEN ||
          data.upstream.readyState === WebSocket.CONNECTING)
      ) {
        data.upstream.close(1000, "client disconnected");
      }
      void this.finalize(data);
    },
  };

  private forward(
    client: Bun.ServerWebSocket<RelaySocketData>,
    message: string | ArrayBuffer | Uint8Array,
  ): void {
    const data = client.data;
    if (data.closing || data.finalized) return;
    try {
      let outbound = message;
      if (data.context.sessionPolicy) {
        if (typeof message !== "string")
          throw new Error("Live requires JSON text");
        outbound = data.context.sessionPolicy.clientMessage(message);
        if (outbound === data.context.sessionPolicy.closeMessage) {
          this.beginClose(client);
          return;
        }
      }
      if ((data.upstream?.bufferedAmount ?? 0) > 1_048_576)
        throw new Error("Backpressure limit");
      data.upstream?.send(outbound);
    } catch {
      if (data.context.sessionPolicy?.protocolErrorMessage &&
        client.readyState === WebSocket.OPEN) {
        client.send(data.context.sessionPolicy.protocolErrorMessage);
      }
      client.close(1008, "unsupported event or stream limit");
      this.beginClose(client);
    }
  }

  private beginClose(client: Bun.ServerWebSocket<RelaySocketData>): void {
    const data = client.data;
    if (data.closing || data.finalized) return;
    data.closing = true;
    if (
      data.context.sessionPolicy &&
      data.upstream?.readyState === WebSocket.OPEN
    ) {
      data.upstream.send(data.context.sessionPolicy.closeMessage);
      // Keep the upstream alive for trusted final usage, even if the client left.
      data.closeTimer = setTimeout(() => {
        data.upstream?.close(1000, "finalization timeout");
        client.close(1000, "session ended");
        void this.finalize(data);
      }, 15_000);
    } else {
      data.upstream?.close(1000, "session ended");
      client.close(1000, "session ended");
      void this.finalize(data);
    }
  }

  private async finalize(data: RelaySocketData): Promise<void> {
    if (data.finalized) return;
    data.finalized = true;
    data.stopAuthority?.();
    if (data.lifetimeTimer) clearTimeout(data.lifetimeTimer);
    if (data.closeTimer) clearTimeout(data.closeTimer);
    try {
      await data.context.onClosed(data.accepted);
    } catch {
      console.error(
        "Realtime accounting finalization failed; reservation requires reconciliation",
      );
    }
  }
}

