input.content:
/**
 * Mechanical parity checklist: every candidate UI item in Source TSX, with an
 * automatic copy check against the native Rust sources.
 *
 * Items are what a writer can see or do: handlers, controls, ARIA, rendered
 * states (conditional branches inside JSX), copy, handled keys, persisted keys
 * and motion classes. Copy that also appears in native Rust is marked
 * `copyNative`; it proves the string exists, not that the surface matches.
 *
 *   bun desktop/gpui/tools/parity-inventory/extract.ts [--out dir]
 */
import ts from "typescript";
import { readdirSync, readFileSync, statSync, mkdirSync, writeFileSync } from "node:fs";
import { join, relative, resolve } from "node:path";

const root = resolve(import.meta.dir, "../../../..");
const outDir = resolve(
  process.argv.includes("--out") ? process.argv[process.argv.indexOf("--out") + 1]! : join(root, "desktop/gpui/target/parity-inventory"),
);

type Kind = "handler" | "control" | "aria" | "state" | "copy" | "key" | "persist" | "motion";
interface Item {
  id: string;
  file: string;
  line: number;
  kind: Kind;
  detail: string;
  copyNative?: boolean;
}

function walk(dir: string, accept: (path: string) => boolean, found: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    if (name === "node_modules" || name === "target" || name.startsWith(".")) continue;
    const path = join(dir, name);
    if (statSync(path).isDirectory()) walk(path, accept, found);
    else if (accept(path)) found.push(path);
  }
  return found;
}

const sourceFiles = walk(join(root, "src"), (p) => p.endsWith(".tsx") && !/\.(test|stories)\.tsx$/.test(p)).sort();

// Native copy corpus: every Rust string literal, whitespace-normalised.
const norm = (s: string) => s.replace(/\s+/g, " ").replace(/[‘’]/g, "'").replace(/[“”]/g, '"').trim().toLowerCase();
const nativeText = walk(join(root, "desktop/gpui/src"), (p) => p.endsWith(".rs"))
  .map((p) => readFileSync(p, "utf8"))
  .join("\n");
const nativeStrings = norm(
  [...nativeText.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((m) => m[1]!.replace(/\\n/g, " ").replace(/\\"/g, '"')).join("\n"),
);

const CONTROL_TAGS = new Set(["button", "input", "select", "textarea", "a", "details", "summary", "dialog", "label", "option", "form"]);
const COPY_ATTRS = new Set(["title", "placeholder", "aria-label", "alt", "label", "aria-description", "aria-roledescription"]);
const MOTION = /\b(transition|animate|duration-|ease-|motion-)/;
const PERSIST_CALL = /^(localStorage|sessionStorage)\.(getItem|setItem|removeItem)$|^(save|load|delete|clear)\w*(Idb|IDB|Meta)$/;

function tagName(node: ts.JsxOpeningLikeElement): string {
  return node.tagName.getText();
}

function attrText(node: ts.JsxOpeningLikeElement, name: string): string | undefined {
  for (const prop of node.attributes.properties) {
    if (ts.isJsxAttribute(prop) && prop.name.getText() === name && prop.initializer) {
      if (ts.isStringLiteral(prop.initializer)) return prop.initializer.text;
      if (ts.isJsxExpression(prop.initializer) && prop.initializer.expression && ts.isStringLiteralLike(prop.initializer.expression))
        return prop.initializer.expression.text;
    }
  }
  return undefined;
}

function label(node: ts.JsxOpeningLikeElement): string {
  const name = attrText(node, "aria-label") ?? attrText(node, "title") ?? attrText(node, "placeholder") ?? attrText(node, "name") ?? attrText(node, "id");
  const parent = node.parent;
  let text = "";
  if (ts.isJsxElement(parent)) {
    text = parent.children
      .filter(ts.isJsxText)
      .map((c) => c.text.trim())
      .filter(Boolean)
      .join(" ");
  }
  return [tagName(node), name ? `"${name}"` : "", text ? `‹${text.slice(0, 60)}›` : ""].filter(Boolean).join(" ");
}

const clip = (s: string, n = 140) => (s.length > n ? `${s.slice(0, n - 1)}…` : s).replace(/\s+/g, " ");

function inJsx(node: ts.Node): boolean {
  for (let p = node.parent; p; p = p.parent) {
    if (ts.isJsxExpression(p)) return true;
    if (ts.isFunctionLike(p) || ts.isSourceFile(p)) return false;
  }
  return false;
}

function containsJsxOrString(node: ts.Node): boolean {
  let hit = false;
  const visit = (n: ts.Node) => {
    if (hit) return;
    if (ts.isJsxElement(n) || ts.isJsxSelfClosingElement(n) || ts.isJsxFragment(n) || ts.isStringLiteralLike(n)) hit = true;
    else ts.forEachChild(n, visit);
  };
  visit(node);
  return hit;
}

const items: Item[] = [];
for (const path of sourceFiles) {
  const file = relative(root, path);
  const text = readFileSync(path, "utf8");
  const sf = ts.createSourceFile(path, text, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX);
  let n = 0;
  const add = (node: ts.Node, kind: Kind, detail: string, copy?: string) => {
    const line = sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
    const item: Item = { id: `${file}:${line}:${kind}:${n++}`, file, line, kind, detail: clip(detail) };
    if (copy !== undefined) {
      const c = norm(copy);
      item.copyNative = c.length >= 3 && nativeStrings.includes(c);
    }
    items.push(item);
  };
  const visit = (node: ts.Node) => {
    if (ts.isJsxOpeningElement(node) || ts.isJsxSelfClosingElement(node)) {
      const tag = tagName(node);
      if (CONTROL_TAGS.has(tag) || attrText(node, "role")) add(node, "control", label(node));
      for (const prop of node.attributes.properties) {
        if (!ts.isJsxAttribute(prop)) continue;
        const name = prop.name.getText();
        if (/^(on[A-Z]\w*\$?|preventdefault:\w+|bind:\w+)$/.test(name)) add(prop, "handler", `${name} on ${label(node)}`);
        else if (name === "role" || name.startsWith("aria-")) {
          const value = attrText(node, name);
          if (value !== undefined) add(prop, "aria", `${name}=${value} on ${tag}`);
          if (value && COPY_ATTRS.has(name)) add(prop, "copy", value, value);
        } else if (COPY_ATTRS.has(name)) {
          const value = attrText(node, name);
          if (value) add(prop, "copy", value, value);
        } else if (name === "class" || name === "className") {
          const value = prop.initializer?.getText(sf) ?? "";
          if (MOTION.test(value)) add(prop, "motion", `${tag}: ${value.match(/[\w:-]*(transition|animate|duration-|ease-|motion-)[\w\[\]\-.:/]*/g)?.join(" ")}`);
        }
      }
    } else if (ts.isJsxText(node)) {
      const t = node.text.replace(/\s+/g, " ").trim();
      if (/[A-Za-z]{2,}/.test(t)) add(node, "copy", t, t);
    } else if ((ts.isConditionalExpression(node) || (ts.isBinaryExpression(node) && [ts.SyntaxKind.AmpersandAmpersandToken, ts.SyntaxKind.BarBarToken, ts.SyntaxKind.QuestionQuestionToken].includes(node.operatorToken.kind))) && inJsx(node) && containsJsxOrString(node)) {
      const cond = ts.isConditionalExpression(node) ? node.condition.getText(sf) : node.left.getText(sf);
      add(node, "state", `when ${cond}`);
    } else if (ts.isStringLiteralLike(node) && inJsx(node) && /[A-Za-z]{2,}\s/.test(node.text) && !ts.isJsxAttribute(node.parent) && !ts.isImportDeclaration(node.parent)) {
      // Copy chosen by a state branch, e.g. {busy ? "Saving…" : "Save"}.
      add(node, "copy", node.text, node.text);
    } else if (ts.isBinaryExpression(node) && [ts.SyntaxKind.EqualsEqualsEqualsToken, ts.SyntaxKind.EqualsEqualsToken].includes(node.operatorToken.kind)) {
      const sides = [node.left, node.right];
      const keySide = sides.find((s) => ts.isPropertyAccessExpression(s) && ["key", "code"].includes(s.name.text));
      const lit = sides.find(ts.isStringLiteralLike);
      if (keySide && lit) add(node, "key", `${keySide.getText(sf)} === "${lit.text}"`);
    } else if (ts.isCaseClause(node) && ts.isStringLiteralLike(node.expression)) {
      const sw = node.parent.parent;
      if (ts.isSwitchStatement(sw) && /\.(key|code)$/.test(sw.expression.getText(sf))) add(node, "key", `${sw.expression.getText(sf)} case "${node.expression.text}"`);
    } else if (ts.isCallExpression(node)) {
      const callee = node.expression.getText(sf);
      if (PERSIST_CALL.test(callee) || /\.(getItem|setItem)$/.test(callee)) {
        const arg = node.arguments[0];
        add(node, "persist", `${callee}(${arg ? clip(arg.getText(sf), 60) : ""})`);
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sf);
}

// Per-file summary: copy coverage is the fast signal for "does this surface exist natively at all".
const byFile = new Map<string, { file: string; items: number; kinds: Record<string, number>; copy: number; copyNative: number }>();
for (const it of items) {
  const s = byFile.get(it.file) ?? { file: it.file, items: 0, kinds: {}, copy: 0, copyNative: 0 };
  s.items++;
  s.kinds[it.kind] = (s.kinds[it.kind] ?? 0) + 1;
