/**
 * Per-state Source drivers. Each `drivers/<state>.ts` default-exports a Driver;
 * a state without a driver file is reported as unmapped, never screenshotted
 * as a stand-in. Port lanes add their own driver files, so the shared capture
 * loop does not change per surface.
 */
import type { Page } from "playwright";

export interface Driver {
  /** Editor view preferences written before load (`twyne:editor:view:v1`). */
  view?: Record<string, unknown>;
  /** Route to open after seeding. Defaults to the writing room. */
  route?: string;
  /** Extra seeding in page context after the shared manuscript and comments. */
  seed?: (page: Page) => Promise<void>;
  /** Wait for the surface the route renders. Defaults to the editor. */
  ready?: (page: Page) => Promise<void>;
  /** Interactions that reach the state, run after `ready`. */
  drive?: (page: Page) => Promise<void>;
  /**
   * True once the lane has checked that Source and native show the same
   * content and state here, so the pixel score measures rendering alone.
   */
  verified?: boolean;
}

export const PARITY_FOLIO = "twyne-gpui-parity";

export async function waitForEditor(page: Page): Promise<void> {
  await page.locator(".ProseMirror").first().waitFor({ timeout: 60_000 });
  await page.getByText("The notebook", { exact: true }).first().waitFor({ timeout: 30_000 });
}

/** Fonts loaded and two frames painted, so the screenshot is settled. */
export async function settle(page: Page): Promise<void> {
  await page.evaluate(async () => {
    await document.fonts.ready;
    await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
  });
}

import { chromium } from "playwright";
import { existsSync } from "node:fs";
import { readFile, mkdir, writeFile, rm } from "node:fs/promises";
import { resolve } from "node:path";
import { PARITY_FOLIO, settle, waitForEditor, type Driver } from "./driver";

const root = process.cwd();
const dir = resolve(root, "desktop/gpui/target/parity");
const states: string[] = JSON.parse(await readFile("desktop/gpui/tools/parity/states.json", "utf8"));
const selected = process.env.PARITY_STATES?.split(",") ?? states;
const html = await readFile("desktop/gpui/fixtures/marginalia/browser-manuscript.html", "utf8");
const comments = JSON.parse(await readFile("desktop/gpui/fixtures/marginalia/browser-comments.json", "utf8"));
await mkdir(`${dir}/web`, { recursive: true });

const results: Record<string, { ok: boolean; verified: boolean; reason: string | null }> = {};
const browser = await chromium.launch({ executablePath: process.env.TWYNE_FIXTURE_CHROME, headless: true });
try {
  for (const state of selected) {
    const output = `${dir}/web/${state}.png`;
    await rm(output, { force: true });
    const driverPath = resolve(import.meta.dir, "drivers", `${state}.ts`);
    if (!existsSync(driverPath)) {
      results[state] = { ok: false, verified: false, reason: `No Source driver: add desktop/gpui/tools/parity/drivers/${state}.ts` };
      console.log("web", state, results[state].reason);
      continue;
    }
    const driver: Driver = (await import(driverPath)).default;
    const context = await browser.newContext({ viewport: { width: 1280, height: 860 }, deviceScaleFactor: 1, reducedMotion: "reduce", colorScheme: "light" });
    try {
      const page = await context.newPage();
      page.setDefaultTimeout(15_000);
      // Only the dev server and fonts load; hosted services stay out of the frame.
      await page.route("**/*", (r) => {
        const u = new URL(r.request().url());
        return ["127.0.0.1", "localhost", "fonts.googleapis.com", "fonts.gstatic.com"].includes(u.hostname) ? r.continue() : r.abort();
      });
      await page.clock.install({ time: new Date("2026-01-01T12:00:00Z") });
      await page.route(/\/api\/auth\//, (r) => r.fulfill({ contentType: "application/json", body: "null" }));
      await page.route("**/__parity_seed", (r) => r.fulfill({ contentType: "text/html", body: "<!doctype html><title>Parity seed</title>" }));
      await page.goto(`${process.env.PARITY_BASE_URL}/__parity_seed`);
      await page.evaluate(
        async ({ html, comments, view, id }) => {
          const path = "/src/utils/idb.ts";
          const db = await import(/* @vite-ignore */ path);
          const now = Date.now();
          await db.saveFoliosToIdb([{ id, name: "The notebook", type: "draft", createdAt: now, updatedAt: now }]);
          await db.saveFolioContentToIdb(id, html);
          await db.saveActiveFolioIdToIdb(id);
          await db.saveCommentsToIdb(comments);
          await db.saveMetaToIdb("signin-toast-dismissed", true);
          await db.saveMetaToIdb("live-review-enabled", false);
          localStorage.setItem("living-desk-open", "false");
          localStorage.setItem("twyne:editor:view:v1", JSON.stringify({ zenMode: false, ...view }));
        },
        { html, comments, view: driver.view ?? {}, id: PARITY_FOLIO },
      );
      await driver.seed?.(page);
      await page.goto(`${process.env.PARITY_BASE_URL}${driver.route ?? "/editor/"}`, { waitUntil: "domcontentloaded", timeout: 120_000 });
      await (driver.ready ?? waitForEditor)(page);
      await driver.drive?.(page);
      await settle(page);
      await page.screenshot({ path: output, animations: "disabled" });
      results[state] = {
        ok: true,
        verified: driver.verified === true,
        reason: driver.verified ? null : "Captured; Source and native content for this state not yet checked identical.",
      };
    } catch (e) {
      results[state] = { ok: false, verified: false, reason: String(e) };
    } finally {
      await context.close();
    }
    console.log("web", state, results[state].reason ?? "ok");
  }
} finally {
  await browser.close();
  await writeFile(`${dir}/web-results.json`, JSON.stringify(results, null, 2) + "\n");
}

