import { Sandbox, CommandExitError } from "e2b";
import { execFileSync } from "node:child_process";
import { lstatSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { resolve, join } from "node:path";
import { createReadStream } from "node:fs";
import { Readable } from "node:stream";

const args = process.argv.slice(2);
const key = process.env.E2B_API_KEY || execFileSync("skate", ["get", "e2b_api_key@secrets"], { encoding: "utf8" }).trim();
const opts = { apiKey: key };
async function inventory() {
  const p = Sandbox.list(opts); const out = [];
  while (p.hasNext) out.push(...await p.nextItems());
  return out.filter(s => s.metadata.project === "twyne-gpui");
}
if (args[0] === "list") {
  console.log(JSON.stringify(await inventory(), null, 2));
} else if (args[0] === "stop") {
  const matches = (await inventory()).filter(s => s.metadata.lane === args[1]);
  if (!args[1] || matches.length !== 1) throw new Error(`Expected exactly one sandbox for lane; found ${matches.length}`);
  await Sandbox.kill(matches[0].sandboxId, opts);
  console.log(`Stopped ${matches[0].sandboxId}`);
} else {
  const sep = args.indexOf("--");
  if (sep < 1 || sep === args.length - 1) throw new Error("Usage: run.ts <worktree> [--lane name] [--keep] [--pull glob] -- <command...>");
  const worktree = resolve(args[0]); let lane = ""; let keep = false; const pulls: string[] = [];
  for (let i = 1; i < sep; i++) {
    if (args[i] === "--lane") lane = args[++i];
    else if (args[i] === "--pull") pulls.push(args[++i]);
    else if (args[i] === "--keep") keep = true;
    else throw new Error(`Unknown option: ${args[i]}`);
  }
  if (pulls.some(p => !p || p.split("/").includes("..") || (p.startsWith("/") && !p.startsWith("/tmp/")))) throw new Error("Pull patterns must be worktree-relative or under /tmp, without ..");
  if (keep && !lane) throw new Error("--keep requires --lane");
  const prior = lane ? (await inventory()).filter(s => s.metadata.lane === lane) : [];
  if (prior.length > 1 || prior.some(s => s.state !== "paused")) throw new Error("Lane is busy or ambiguous; use separate lanes for parallel runs");
  const sb = prior.length ? await Sandbox.connect(prior[0].sandboxId, { ...opts, timeoutMs: 3600000 }) : await Sandbox.create(process.env.TWYNE_E2B_TEMPLATE || "twyne-gpui", { ...opts, timeoutMs: 3600000, metadata: { project: "twyne-gpui", lane } });
  console.error(`Sandbox ${sb.sandboxId}`);
  const tmp = mkdtempSync(join(tmpdir(), "twyne-remote-"));
  let exitCode = 1;
  const q = (v: string) => `'${v.replaceAll("'", "'\\''")}'`;
  try {
