    writeFileSync(join(tmp, "files"), files.join("\0") + "\0");
    execFileSync("tar", ["--null", "--verbatim-files-from", "-czf", join(tmp, "source.tgz"), "-T", join(tmp, "files")], { cwd: worktree });
    await sb.files.write("/tmp/source.tgz", Readable.toWeb(createReadStream(join(tmp, "source.tgz"))) as ReadableStream, { requestTimeoutMs: 1800000 });
