    const argv = args.slice(sep + 1);
    const command = (argv[0] === "devenv" ? argv : ["devenv", "shell", "--", ...argv]).map(q).join(" ");
    try {
      await sb.commands.run(`cd /root/work && . /root/.nix-profile/etc/profile.d/nix.sh && ${command}`, { timeoutMs: 0, onStdout: s => process.stdout.write(s), onStderr: s => process.stderr.write(s) });
      exitCode = 0;
