    if (pulls.length) {
      const py = `import glob,tarfile,os\npatterns=${JSON.stringify(pulls)}\nwith tarfile.open('/tmp/artifacts.tar','w') as t:\n for p in patterns:\n  for f in glob.glob(p,recursive=True):\n   if os.path.isfile(f) and not os.path.islink(f): t.add(f,arcname=f.lstrip('/'),recursive=False)\n`;
