import type { Sandbox } from "e2b";
import { execFileSync } from "node:child_process";
import { createReadStream, lstatSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Readable } from "node:stream";

/**
 * Copy a worktree's tracked and unignored files to /root/work. Only files
 * whose content changed are rewritten, so unchanged files keep the mtimes the
 * warm build saw and Cargo rebuilds just the crates a lane edited.
 */
export async function syncWorktree(sb: Sandbox, worktree: string): Promise<void> {
  const tmp = mkdtempSync(join(tmpdir(), "twyne-remote-"));
  try {
    const present = (p: string) => {
      try {
        lstatSync(join(worktree, p));
        return true;
      } catch (e: any) {
        if (e.code === "ENOENT") return false;
        throw e;
      }
    };
    const files = execFileSync("git", ["ls-files", "-co", "--exclude-standard", "-z"], { cwd: worktree })
      .toString()
      .split("\0")
      .filter((p) => p && present(p) && !p.split("/").some((x) => x === "target" || x === "node_modules"));
    writeFileSync(join(tmp, "files"), files.join("\0") + "\0");
    execFileSync("tar", ["--null", "--verbatim-files-from", "-czf", join(tmp, "source.tgz"), "-T", join(tmp, "files")], { cwd: worktree });
    await sb.files.write("/tmp/source.tgz", Readable.toWeb(createReadStream(join(tmp, "source.tgz"))) as ReadableStream, {
      requestTimeoutMs: 1_800_000,
    });
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
  await sb.commands.run(
    [
      "set -e",
      "command -v rsync >/dev/null || (apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq rsync >/dev/null)",
      "rm -rf /root/stage && mkdir -p /root/stage /root/work /root/cache/target",
      "tar -xzf /tmp/source.tgz -C /root/stage && rm -f /tmp/source.tgz",
      // Content-compared copy: unchanged files keep their mtimes. Excluded
      // build and dependency directories are never deleted.
      "rsync -rlc --delete --exclude=node_modules --exclude=target /root/stage/ /root/work/",
      "rm -rf /root/stage",
