input.content:
/**
 * Detached remote jobs, so a lane can start a build and keep coding:
 *
 *   job.ts start <worktree> --lane L [--pull glob]... -- <command...>
 *   job.ts status <lane>              running | finished (exit N) | paused | none
 *   job.ts logs <lane> [--lines N]    tail of the job's combined output
 *   job.ts pull <worktree> --lane L   copy the job's --pull files back, then pause
 *
 * A job keeps running after `start` returns. New lanes start from the warm
 * snapshot when it exists (see warm.ts), so their first build only recompiles
 * what the lane changed.
 */
import { Sandbox, RateLimitError, ServiceBusyError, SandboxError } from "e2b";
import { execFileSync } from "node:child_process";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { randomUUID } from "node:crypto";
import { syncWorktree } from "./sync";

const key = process.env.E2B_API_KEY || execFileSync("skate", ["get", "e2b_api_key@secrets"], { encoding: "utf8" }).trim();
const opts = { apiKey: key };
const HOUR = 3_600_000;
export const WARM_SNAPSHOT = "twyne-gpui-warm";

async function laneSandboxes(lane: string) {
  const pages = Sandbox.list(opts);
  const out = [];
  while (pages.hasNext) out.push(...(await pages.nextItems()));
  return out.filter((s) => s.metadata.project === "twyne-gpui" && s.metadata.lane === lane);
}

async function templateFor(): Promise<string> {
  if (process.env.TWYNE_E2B_TEMPLATE) return process.env.TWYNE_E2B_TEMPLATE;
  const pages = Sandbox.listSnapshots(opts);
  while (pages.hasNext) for (const snap of await pages.nextItems()) if ((snap as any).names?.includes?.(WARM_SNAPSHOT) || (snap as any).name === WARM_SNAPSHOT) return WARM_SNAPSHOT;
  return "twyne-gpui";
}

/** Connect to the lane's sandbox, resuming it if paused, or create one. */
export async function laneSandbox(lane: string, create: boolean): Promise<Sandbox | null> {
  const found = await laneSandboxes(lane);
  if (found.length > 1) throw new Error(`Lane ${lane} has ${found.length} sandboxes; stop the extras.`);
  if (found.length) return Sandbox.connect(found[0].sandboxId, { ...opts, timeoutMs: HOUR });
  if (!create) return null;
  const template = await templateFor();
  const requestId = randomUUID();
  const start = Date.now();
  for (;;) {
    try {
      const sb = await Sandbox.create(template, {
        ...opts,
        idempotencyKey: requestId,
        timeoutMs: HOUR,
        lifecycle: { onTimeout: { action: "pause", mode: "filesystem" } },
        metadata: { project: "twyne-gpui", lane },
      } as any);
      console.error(`Created ${sb.sandboxId} for lane ${lane} from ${template}`);
      return sb;
    } catch (error) {
      const capacity = error instanceof SandboxError && (error as any).statusCode === 409 && /concurr|capacity|limit|in progress/i.test(error.message);
      if (!(error instanceof RateLimitError || error instanceof ServiceBusyError || capacity) || Date.now() - start > 20 * 60_000) throw error;
      console.error("E2B capacity reached; retrying for up to 20 minutes.");
      await new Promise((r) => setTimeout(r, 10_000 + Math.random() * 5_000));
    }
  }
}

const q = (v: string) => `'${v.replaceAll("'", "'\\''")}'`;

export async function startJob(sb: Sandbox, command: string[], pulls: string[]): Promise<void> {
  const busy = await sb.commands.run("test -f /root/job/pid && ! test -f /root/job/exit && kill -0 $(cat /root/job/pid) 2>/dev/null && echo busy || true");
  if (busy.stdout.includes("busy")) throw new Error("This lane already has a job running; check `status`, or `stop` the lane.");
  const argv = command[0] === "devenv" ? command : ["devenv", "shell", "--", ...command];
  const script = [
    "#!/bin/bash",
    "cd /root/work",
    ". /root/.nix-profile/etc/profile.d/nix.sh",
    "export CARGO_BUILD_JOBS=${CARGO_BUILD_JOBS:-2}",
    argv.map(q).join(" "),
    "echo $? > /root/job/exit.tmp && mv /root/job/exit.tmp /root/job/exit",
  ].join("\n");
  await sb.commands.run("rm -rf /root/job && mkdir -p /root/job");
  await sb.files.write("/root/job/run.sh", script);
  await sb.files.write("/root/job/pulls.json", JSON.stringify(pulls));
  await sb.files.write("/root/job/started", new Date().toISOString());
  await sb.commands.run("chmod +x /root/job/run.sh && setsid nohup /root/job/run.sh > /root/job/log 2>&1 < /dev/null & echo $! > /root/job/pid");
}

export async function jobStatus(sb: Sandbox): Promise<string> {
  const r = await sb.commands.run(
    "if test -f /root/job/exit; then echo finished $(cat /root/job/exit); elif test -f /root/job/pid && kill -0 $(cat /root/job/pid) 2>/dev/null; then echo running; elif test -f /root/job/pid; then echo interrupted; else echo none; fi; cat /root/job/started 2>/dev/null",
  );
  return r.stdout.trim();
}

async function pullArtifacts(sb: Sandbox, worktree: string, extra: string[]): Promise<void> {
  const saved = JSON.parse((await sb.commands.run("cat /root/job/pulls.json 2>/dev/null || echo '[]'")).stdout || "[]");
  const patterns = [...new Set([...saved, ...extra, "/root/job/log"])];
  const py = `import glob,tarfile,os\npatterns=${JSON.stringify(patterns)}\nwith tarfile.open('/tmp/artifacts.tar','w') as t:\n for p in patterns:\n  for f in glob.glob(p,recursive=True):\n   if os.path.isfile(f) and not os.path.islink(f): t.add(f,arcname=('remote-job.log' if f=='/root/job/log' else f.lstrip('/')),recursive=False)\n`;
  await sb.files.write("/tmp/pull.py", py);
  await sb.commands.run("cd /root/work && python3 /tmp/pull.py", { timeoutMs: 0 });
  const tmp = mkdtempSync(join(tmpdir(), "twyne-pull-"));
  try {
    writeFileSync(join(tmp, "a.tar"), await sb.files.read("/tmp/artifacts.tar", { format: "bytes" }));
    const extract = `import os,sys,tarfile\nroot=os.path.realpath(sys.argv[2])\nwith tarfile.open(sys.argv[1]) as t:\n for m in t.getmembers():\n  path=os.path.join(root,m.name)\n  if not m.isfile() or os.path.commonpath([root,os.path.realpath(path)]) != root: raise ValueError("unsafe artifact path")\n t.extractall(root,filter="data")\n`;
    execFileSync("python3", ["-c", extract, join(tmp, "a.tar"), worktree]);
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

if (import.meta.main) {
  const [verb, ...rest] = process.argv.slice(2);
  const flag = (name: string) => {
    const i = rest.indexOf(name);
    return i >= 0 ? rest[i + 1] : undefined;
  };
  const flags = (name: string) => rest.flatMap((v, i) => (v === name && rest[i + 1] ? [rest[i + 1]!] : []));
  if (verb === "start") {
    const sep = rest.indexOf("--");
    const lane = flag("--lane");
    if (!lane || sep < 1 || sep === rest.length - 1) throw new Error("Usage: job.ts start <worktree> --lane L [--pull glob]... -- <command...>");
    const sb = (await laneSandbox(lane, true))!;
    await syncWorktree(sb, resolve(rest[0]!));
    await startJob(sb, rest.slice(sep + 1), flags("--pull"));
    console.log(`Started on lane ${lane} (${sb.sandboxId}). Check with: bun run desktop.gpui.job status ${lane}`);
  } else if (verb === "status" || verb === "logs") {
    const sb = await laneSandbox(rest[0]!, false);
    if (!sb) {
      console.log("none");
    } else if (verb === "status") {
      console.log(await jobStatus(sb));
    } else {
      const n = Number(flag("--lines") ?? 60);
      console.log((await sb.commands.run(`tail -n ${n} /root/job/log 2>/dev/null || true`)).stdout);
    }
  } else if (verb === "pull") {
    const lane = flag("--lane");
    if (!lane) throw new Error("Usage: job.ts pull <worktree> --lane L [--pull glob]...");
    const sb = await laneSandbox(lane, false);
    if (!sb) throw new Error(`No sandbox for lane ${lane}`);
    const status = await jobStatus(sb);
    if (status.startsWith("running")) throw new Error("The job is still running; pull after `status` reports finished.");
    await pullArtifacts(sb, resolve(rest[0]!), flags("--pull"));
    await sb.pause({ mode: "filesystem", ...opts } as any);
    console.log(`${status.split("\n")[0]}. Artifacts and remote-job.log copied; lane paused.`);
  } else {
    throw new Error("Usage: job.ts start|status|logs|pull …");
  }
}

