/**
 * Move lanes whose sandbox booted before the warm snapshot existed onto it,
 * keeping each lane's queued job: the job script and pull list are copied,
 * the cold sandbox is killed, and the same job restarts on a warm sandbox
 * synced from the lane's worktree. `status` keeps working for the lane.
 *
 *   bun desktop/gpui/tools/remote/rewarm.ts lane=worktree [lane=worktree...]
 */
import { Sandbox } from "e2b";
import { e2bKey } from "./key";
import { laneSandbox } from "./job";
import { syncWorktree } from "./sync";

const opts = { apiKey: e2bKey() };
const pages = Sandbox.list(opts);
const live = [];
while (pages.hasNext) live.push(...(await pages.nextItems()));

await Promise.all(
  process.argv.slice(2).map(async (pair) => {
    const [lane, worktree] = pair.split("=") as [string, string];
    const info = live.find((s) => s.metadata.project === "twyne-gpui" && s.metadata.lane === lane);
    if (!info) return console.log(`${lane}: no sandbox, skipped`);
    if (!info.templateId?.startsWith("rzftso5d9wll")) return console.log(`${lane}: already warm, skipped`);
    const cold = await Sandbox.connect(info.sandboxId, opts);
    const read = async (path: string) => (await cold.commands.run(`cat ${path} 2>/dev/null; true`)).stdout;
    const script = await read("/root/job/run.sh");
    const pulls = (await read("/root/job/pulls.json")) || "[]";
    await Sandbox.kill(info.sandboxId, opts);
    const sb = (await laneSandbox(lane, true))!;
    await syncWorktree(sb, worktree);
    if (!script.trim()) return console.log(`${lane}: warm sandbox ${sb.sandboxId}, no job was queued`);
    await sb.commands.run("rm -rf /root/job && mkdir -p /root/job");
    // The warm build ran six jobs without running out of memory.
    await sb.files.write("/root/job/run.sh", script.replace("${CARGO_BUILD_JOBS:-2}", "${CARGO_BUILD_JOBS:-6}"));
    await sb.files.write("/root/job/pulls.json", pulls);
    await sb.files.write("/root/job/started", new Date().toISOString());
    await sb.commands.run("chmod +x /root/job/run.sh");
    await sb.commands.run("echo $$ > /root/job/pid; exec /root/job/run.sh > /root/job/log 2>&1 < /dev/null", {
      background: true,
      timeoutMs: 0,
    });
    console.log(`${lane}: job restarted on warm sandbox ${sb.sandboxId}`);
  }),
);

