/**
 * Remote desktop builds on Railway sandboxes. Each port lane gets its own
 * sandbox, booted from the warm checkpoint (toolchain, dependencies, helper,
 * and the ui-tests binary and tests already built), and runs detached jobs:
 *
 *   railway.ts start <worktree> --lane L [--pull glob]... -- <command...>
 *   railway.ts status <lane>              running | finished N | interrupted | none
 *   railway.ts logs <lane> [--lines N]    tail of the job's combined output
 *   railway.ts pull <worktree> --lane L   copy --pull files and remote-job.log back
 *   railway.ts stop <lane>                destroy the lane's sandbox
 *   railway.ts list                       lane sandboxes and their status
 *   railway.ts warm <worktree>            rebuild the warm checkpoint from a worktree
 *
 * Commands run inside `devenv shell` at /root/work, so they use the project's
 * pinned toolchain. Lanes are recorded in ~/.config/twyne/railway-lanes.json.
 */
import { execFileSync, spawn } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { homedir, tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";

const PROJECT = process.env.TWYNE_RAILWAY_PROJECT ?? "e4ceb8e6-e1b1-40ca-b6f6-9ee227f0c7c3";
const ENVIRONMENT = process.env.TWYNE_RAILWAY_ENVIRONMENT ?? "c57775d5-e7c1-4c70-a974-7b0326c32199";
export const BASE_CHECKPOINT = "twyne-gpui-base";
export const WARM_CHECKPOINT = "twyne-gpui-warm";
const LANES = join(homedir(), ".config/twyne/railway-lanes.json");
const scope = ["--project", PROJECT, "--environment", ENVIRONMENT];
// The sandbox shell runs without $USER, which Nix's profile script needs.
const PRELUDE = "export USER=root HOME=/root; . /root/.nix-profile/etc/profile.d/nix.sh";

type Lanes = Record<string, string>;
const readLanes = (): Lanes => (existsSync(LANES) ? JSON.parse(readFileSync(LANES, "utf8")) : {});
function writeLanes(lanes: Lanes) {
  mkdirSync(dirname(LANES), { recursive: true });
  writeFileSync(LANES, JSON.stringify(lanes, null, 2) + "\n");
}

function railway(args: string[], input?: Buffer | string): string {
  return execFileSync("railway", ["sandbox", ...args, ...scope], {
    input,
    maxBuffer: 1 << 30,
    stdio: ["pipe", "pipe", "pipe"],
  })
    .toString()
    .split("\n")
    .filter((line) => !line.startsWith("Warning: Railway sandboxes are experimental"))
    .join("\n");
}

/** Run a shell command in the sandbox; stdout is returned, stdin optional. */
export function exec(id: string, command: string, input?: Buffer | string, timeoutSeconds = 1800): string {
  return railway(["exec", "--id", id, "--timeout", String(timeoutSeconds), "--", `${PRELUDE}; ${command}`], input);
}

interface SandboxInfo {
  id: string;
  status: string;
}
function sandboxes(): SandboxInfo[] {
  return JSON.parse(railway(["list", "--json"]) || "[]");
}
function checkpoints(): string[] {
  try {
    return (JSON.parse(railway(["checkpoint", "list", "--json"]) || "[]") as { name: string }[]).map((c) => c.name);
  } catch {
    return [];
  }
}

function waitRunning(id: string) {
  for (let i = 0; i < 120; i++) {
    const s = sandboxes().find((x) => x.id === id);
    if (s?.status === "RUNNING") return;
    if (s && /FAIL|DESTROY|STOP/.test(s.status)) throw new Error(`Sandbox ${id} is ${s.status}`);
    execFileSync("sleep", ["2"]);
  }
  throw new Error(`Sandbox ${id} did not start`);
}

/** The lane's live sandbox, or a new one booted from the warm checkpoint. */
export function laneSandbox(lane: string, create: boolean): string | null {
  const lanes = readLanes();
  const known = lanes[lane];
  if (known && sandboxes().some((s) => s.id === known && s.status === "RUNNING")) return known;
  if (!create) return null;
  const names = checkpoints();
  const from = names.includes(WARM_CHECKPOINT) ? WARM_CHECKPOINT : BASE_CHECKPOINT;
  const created = JSON.parse(
    railway(["create", "--checkpoint", from, "--idle-timeout-minutes", "120", "--json"]),
  ) as SandboxInfo;
  waitRunning(created.id);
  lanes[lane] = created.id;
  writeLanes(lanes);
  console.error(`Created ${created.id} for lane ${lane} from ${from}`);
  return created.id;
}

/** Media and video projects the build and captures never read. */
const SKIP = ["launch-videos/", "public/assets/manual/narration/"];

/**
 * Stream the worktree's tracked and unignored files into /root/work. Only
 * files whose content changed are rewritten, so Cargo rebuilds just what the
 * lane edited.
 */
export function syncWorktree(id: string, worktree: string) {
  const files = execFileSync("git", ["ls-files", "-co", "--exclude-standard", "-z"], { cwd: worktree })
    .toString()
    .split("\0")
    .filter(
      (p) =>
        p &&
        existsSync(join(worktree, p)) &&
        !p.split("/").some((x) => x === "target" || x === "node_modules") &&
        !SKIP.some((prefix) => p.startsWith(prefix)) &&
        !/\.(mp4|mov|webm|m4a|wav|mp3)$/i.test(p),
    );
  const tmp = mkdtempSync(join(tmpdir(), "twyne-railway-"));
  try {
    writeFileSync(join(tmp, "files"), files.join("\0") + "\0");
    execFileSync("tar", ["--null", "--verbatim-files-from", "-czf", join(tmp, "src.tgz"), "-T", join(tmp, "files")], { cwd: worktree });
    exec(
      id,
      [
        "set -e",
        "rm -rf /root/stage && mkdir -p /root/stage /root/work /root/cache/target",
        "tar -xzf - -C /root/stage",
        "rsync -rlc --delete --exclude=node_modules --exclude=target /root/stage/ /root/work/",
        "rm -rf /root/stage",
        "mkdir -p /root/work/desktop/gpui && ln -sfn /root/cache/target /root/work/desktop/gpui/target",
      ].join(" && "),
      readFileSync(join(tmp, "src.tgz")),
    );
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

const q = (v: string) => `'${v.replaceAll("'", "'\\''")}'`;

export function startJob(id: string, command: string[], pulls: string[]) {
  if (exec(id, "test -f /root/job/pid && ! test -f /root/job/exit && kill -0 $(cat /root/job/pid) 2>/dev/null && echo busy; true").includes("busy"))
    throw new Error("This lane already has a job running; check `status`, or `stop` the lane.");
  const argv = command[0] === "devenv" ? command : ["devenv", "shell", "--", ...command];
  const script = [
    "#!/bin/bash",
    PRELUDE,
    "cd /root/work",
    "export CARGO_BUILD_JOBS=${CARGO_BUILD_JOBS:-6}",
    argv.map(q).join(" "),
    "echo $? > /root/job/exit.tmp && mv /root/job/exit.tmp /root/job/exit",
  ].join("\n");
  exec(id, "rm -rf /root/job && mkdir -p /root/job && cat > /root/job/run.sh && chmod +x /root/job/run.sh", script);
  exec(id, "cat > /root/job/pulls.json", JSON.stringify(pulls));
  exec(id, `date -u +%FT%TZ > /root/job/started; setsid bash -c 'echo $$ > /root/job/pid; exec /root/job/run.sh > /root/job/log 2>&1 < /dev/null' & disown; sleep 1; test -s /root/job/pid`);
}

export function jobStatus(id: string): string {
  return exec(
    id,
    "if test -f /root/job/exit; then echo finished $(cat /root/job/exit); elif test -f /root/job/pid && kill -0 $(cat /root/job/pid) 2>/dev/null; then echo running; elif test -f /root/job/pid; then echo interrupted; else echo none; fi; cat /root/job/started 2>/dev/null; true",
  ).trim();
}

function pull(id: string, worktree: string, extra: string[]) {
  const saved = JSON.parse(exec(id, "cat /root/job/pulls.json 2>/dev/null || echo '[]'").trim() || "[]");
  const patterns = [...new Set([...saved, ...extra])];
  const py = `import glob,tarfile,os,sys\npatterns=${JSON.stringify(patterns)}\nwith tarfile.open(fileobj=sys.stdout.buffer,mode='w|gz') as t:\n if os.path.isfile('/root/job/log'): t.add('/root/job/log',arcname='remote-job.log')\n for p in patterns:\n  for f in glob.glob(p,recursive=True):\n   if os.path.isfile(f) and not os.path.islink(f): t.add(f,arcname=f.lstrip('/'),recursive=False)\n`;
  const tmp = mkdtempSync(join(tmpdir(), "twyne-pull-"));
  try {
    const out = execFileSync(
      "railway",
      ["sandbox", "exec", "--id", id, "--timeout", "1800", ...scope, "--", `${PRELUDE}; cd /root/work && python3 -c ${q(py)} | base64 -w0`],
      { maxBuffer: 1 << 30 },
    )
      .toString()
      .split("\n")
      .filter((l) => !l.startsWith("Warning:"))
      .join("");
    writeFileSync(join(tmp, "a.tgz"), Buffer.from(out.trim(), "base64"));
    const extract = `import os,sys,tarfile\nroot=os.path.realpath(sys.argv[2])\nwith tarfile.open(sys.argv[1]) as t:\n for m in t.getmembers():\n  path=os.path.join(root,m.name)\n  if not m.isfile() or os.path.commonpath([root,os.path.realpath(path)]) != root: raise ValueError("unsafe artifact path")\n t.extractall(root,filter="data")\n`;
    execFileSync("python3", ["-c", extract, join(tmp, "a.tgz"), worktree]);
  } finally {
    rmSync(tmp, { recursive: true, force: true });
  }
}

function destroy(lane: string) {
  const lanes = readLanes();
  const id = lanes[lane];
  if (!id) return console.log(`No sandbox for lane ${lane}`);
  try {
    railway(["destroy", id]);
  } catch {}
  delete lanes[lane];
  writeLanes(lanes);
  console.log(`Destroyed ${id}`);
}

export const WARM_COMMAND = [
  "bash",
  "-c",
  "bun install --frozen-lockfile && bun run desktop.gpui.build-helper && cargo build --locked --features ui-tests --manifest-path desktop/gpui/Cargo.toml --bin twyne-desktop && cargo test --locked --features ui-tests --manifest-path desktop/gpui/Cargo.toml --no-run",
];

if (import.meta.main) {
  const [verb, ...rest] = process.argv.slice(2);
  const flag = (name: string) => {
    const i = rest.indexOf(name);
    return i >= 0 ? rest[i + 1] : undefined;
  };
  const flags = (name: string) => rest.flatMap((v, i) => (v === name && rest[i + 1] ? [rest[i + 1]!] : []));
  if (verb === "start") {
    const sep = rest.indexOf("--");
    const lane = flag("--lane");
    if (!lane || sep < 1 || sep === rest.length - 1) throw new Error("Usage: railway.ts start <worktree> --lane L [--pull glob]... -- <command...>");
    const id = laneSandbox(lane, true)!;
    syncWorktree(id, resolve(rest[0]!));
    startJob(id, rest.slice(sep + 1), flags("--pull"));
    console.log(`Started on lane ${lane} (${id}). Check with: bun run desktop.gpui.job status ${lane}`);
  } else if (verb === "status" || verb === "logs") {
    const id = laneSandbox(rest[0]!, false);
    if (!id) console.log("none");
    else if (verb === "status") console.log(jobStatus(id));
    else console.log(exec(id, `tail -n ${Number(flag("--lines") ?? 60)} /root/job/log 2>/dev/null; true`));
  } else if (verb === "pull") {
    const lane = flag("--lane");
    if (!lane) throw new Error("Usage: railway.ts pull <worktree> --lane L [--pull glob]...");
    const id = laneSandbox(lane, false);
    if (!id) throw new Error(`No sandbox for lane ${lane}`);
    const status = jobStatus(id);
    if (status.startsWith("running")) throw new Error("The job is still running; pull after `status` reports finished.");
    pull(id, resolve(rest[0]!), flags("--pull"));
    console.log(`${status.split("\n")[0]}. Artifacts and remote-job.log copied.`);
  } else if (verb === "stop") {
    destroy(rest[0]!);
  } else if (verb === "list") {
    const live = new Map(sandboxes().map((s) => [s.id, s.status]));
    for (const [lane, id] of Object.entries(readLanes())) console.log(`${lane.padEnd(18)} ${id} ${live.get(id) ?? "gone"}`);
  } else if (verb === "warm") {
    const id = laneSandbox("warm-checkpoint", true)!;
    syncWorktree(id, resolve(rest[0] ?? "."));
    startJob(id, WARM_COMMAND, []);
    console.error(`Warming on ${id}`);
    for (;;) {
      execFileSync("sleep", ["60"]);
      const status = jobStatus(id);
      console.error(status.split("\n")[0]);
      if (status.startsWith("running")) continue;
      if (!status.startsWith("finished 0")) {
        console.error(exec(id, "tail -n 80 /root/job/log"));
        process.exit(1);
      }
      break;
    }
    exec(id, "rm -rf /root/job");
    railway(["checkpoint", "create", WARM_CHECKPOINT, "--id", id]);
    console.log(`Checkpoint ${WARM_CHECKPOINT} saved from ${id}`);
    destroy("warm-checkpoint");
  } else {
    throw new Error("Usage: railway.ts start|status|logs|pull|stop|list|warm …");
  }
}
