/// in tools/parity/states.d/*.json, so lanes add states without editing a
/// shared list. Captures always run from the build tree.
fn capture_state_known(state: &str) -> bool {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tools/parity");
    let mut files = vec![dir.join("states.json")];
    if let Ok(entries) = std::fs::read_dir(dir.join("states.d")) {
        files.extend(
            entries
                .flatten()
                .map(|entry| entry.path())
                .filter(|path| path.extension().is_some_and(|ext| ext == "json")),
        );
    }
    files.iter().any(|path| {
        std::fs::read_to_string(path)
            .ok()
            .and_then(|text| serde_json::from_str::<Vec<String>>(&text).ok())
            .is_some_and(|names| names.iter().any(|name| name == state))
    })
}

